            if constexpr (Sorted) {
                if (p < points[i - 1]) throw std::invalid_argument("convex_hull_sorted: points are not sorted");
            }
#endif
            if constexpr (!Sorted) ordered = ordered && !(p < points[i - 1]);
        }
