                            ++counts[2][(key >> 16) & 255];
                            ++counts[3][(key >> 24) & 255];
                            ++counts[4][(key >> 32) & 255];
                            ++counts[5][(key >> 40) & 255];
                            ++counts[6][(key >> 48) & 255];
