                        std::size_t sum = 0;
                        for (auto& n : count) {
                            const auto next = sum + n;
                            n = sum;
                            sum = next;
                        }
                        for (auto key : keys) temp[count[(key >> shift) & 255]++] = key;
                        keys.swap(temp);
                    }
