    auto left_turn = [&](const geo::Point<T, C>& a, const geo::Point<T, C>& b, const geo::Point<T, C>& c) {
        if constexpr (std::is_integral_v<T>) {
            if (narrow) {
                const auto ux = std::int64_t(b.x) - std::int64_t(a.x), uy = std::int64_t(b.y) - std::int64_t(a.y);
