#include HEADER
#include <chrono>
#include <iostream>
#include <random>
#include <string>
#include <limits>
template<class P>int run(int n,int shape,int loops){
 std::mt19937_64 rng(91271);std::vector<P>points;points.reserve(n);
 for(int i=0;i<n;++i){std::int64_t x=static_cast<std::int64_t>(rng()%2000000001)-1000000000,y=static_cast<std::int64_t>(rng()%2000000001)-1000000000;
 if(shape==1){x=i-n/2;y=x*x;}
 if(shape==3){x%=8;y%=8;}
 if(shape==4){x=i;y=0;}
 if(shape==5){x*=1000000;y*=1000000;}
 if(shape==9){x=std::numeric_limits<std::int64_t>::max()-2000000000+x;y=std::numeric_limits<std::int64_t>::min()+2000000000+y;}
 points.push_back({static_cast<typename P::Value>(x),static_cast<typename P::Value>(y)});}
 if(shape==1||shape==4)std::shuffle(points.begin(),points.end(),rng);
 if(shape==7||shape==8)std::sort(points.begin(),points.end());
 auto once=[&]{auto hull=shape==7?convex_hull_sorted(points):geo::convex_hull(points);std::uint64_t hash=hull.size();for(const auto&p:hull)hash=hash*769+static_cast<std::uint64_t>(static_cast<std::int64_t>(p.x))*17+static_cast<std::uint64_t>(static_cast<std::int64_t>(p.y));return hash;};auto hash=once();auto start=std::chrono::steady_clock::now();for(int i=0;i<loops;++i)hash+=once();auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<hash<<'\n';return 0;}
int main(int argc,char**argv){if(argc!=4)return 1;int n=std::stoi(argv[1]),shape=std::stoi(argv[2]),loops=std::stoi(argv[3]);if(shape==6)return run<geo::Point<double>>(n,shape,loops);return run<geo::PointI>(n,shape,loops);}

